import { dictionary } from "./dictionary";

window.mostrarEstado = function(mensaje, tipo = "info") {
  const statusDiv = document.getElementById("status");
  const statusMessage = document.getElementById("status-message");

  if (!statusDiv || !statusMessage) {
    console.warn("Elementos de estado aún no disponibles en el DOM.");
    return;
  }

  statusMessage.textContent = mensaje;
  statusDiv.style.display = "block";

  // Colores según el tipo
  if (tipo === "success") {
    statusDiv.style.backgroundColor = "#dff6dd";
    statusDiv.style.color = "#107c10";
    statusDiv.style.border = "1px solid #107c10";
  } else if (tipo === "error") {
    statusDiv.style.backgroundColor = "#fde7e9";
    statusDiv.style.color = "#a80000";
    statusDiv.style.border = "1px solid #a80000";
  } else {
    statusDiv.style.backgroundColor = "#f3f2f1";
    statusDiv.style.color = "#323130";
    statusDiv.style.border = "1px solid #8a8886";
  }

  // Ocultar después de 5 segundos si es éxito
  if (tipo === "success") {
    setTimeout(() => {
      statusDiv.style.display = "none";
    }, 5000);
  }
};

// ------------------------------
// Optimized matcher (trie-based) — builds lazily and reuses across calls
// ------------------------------
let _matcher = null;

function buildMatcherFromDictionary(dict) {
  if (_matcher) return _matcher;

  const root = { children: Object.create(null), isTerminal: false, replacementHTML: null };

  for (const rule of dict) {
    // build replacement HTML once per rule
    let replacementHTML = "";
    for (const part of rule.replacement) {
      replacementHTML += part.bold ? `<strong>${part.text}</strong>` : part.text;
    }

    for (const variant of rule.matches) {
      const key = String(variant).normalize('NFC').toLowerCase();
      let node = root;
      for (const ch of key) {
        if (!node.children[ch]) node.children[ch] = { children: Object.create(null), isTerminal: false, replacementHTML: null };
        node = node.children[ch];
      }
      // if multiple variants map to same terminal, first one wins (stable)
      if (!node.isTerminal) {
        node.isTerminal = true;
        node.replacementHTML = replacementHTML;
      }
    }
  }

  _matcher = root;
  return _matcher;
}

// Unicode-aware word char test with fallback for older engines
const _unicodeWordCharSupported = (() => {
  try {
    new RegExp('\\p{L}', 'u');
    return true;
  } catch (e) {
    return false;
  }
})();

function isWordChar(ch) {
  if (!ch || ch.length === 0) return false;
  if (_unicodeWordCharSupported) {
    return /\p{L}|\p{N}/u.test(ch);
  }
  // Fallback: Latin letters and numbers ranges (covers common accented chars)
  return /[A-Za-z0-9\u00C0-\u024F\u1E00-\u1EFF]/.test(ch);
}

function normalizeHtmlUsingTrie(html, dict) {
  // Returns { html: string, changes: number }
  if (typeof html !== 'string') return { html, changes: 0 };
  try {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');

    const matcher = buildMatcherFromDictionary(dict);

    const walker = doc.createTreeWalker(doc.body || doc, NodeFilter.SHOW_TEXT, null, false);

    let node = walker.nextNode();
    const skipParentTags = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT']);
    let changes = 0;

    while (node) {
      const parent = node.parentElement;
      if (parent && skipParentTags.has(parent.tagName)) {
        node = walker.nextNode();
        continue;
      }

      let text = node.nodeValue;
      if (!text || text.length === 0) {
        node = walker.nextNode();
        continue;
      }

      let lower = text.normalize('NFC').toLowerCase();

      let pos = 0;
      while (pos < lower.length) {
        let cur = matcher;
        let matchLen = 0;
        let matchReplacementHTML = null;

        for (let j = pos; j < lower.length; j++) {
          const ch = lower[j];
          if (!cur.children[ch]) break;
          cur = cur.children[ch];
          if (cur.isTerminal) {
            matchLen = j - pos + 1;
            matchReplacementHTML = cur.replacementHTML;
          }
        }

        if (matchLen === 0) {
          pos += 1;
          continue;
        }

        const prevChar = pos === 0 ? null : text[pos - 1];
        const nextChar = pos + matchLen >= text.length ? null : text[pos + matchLen];

        // enforce whole-word boundaries
        if ((prevChar && isWordChar(prevChar)) || (nextChar && isWordChar(nextChar))) {
          pos += 1;
          continue;
        }

        // Perform replacement within this text node by splitting
        // Steps: node.splitText(pos) -> afterNode (match+rest), afterNode.splitText(matchLen) -> restNode
        const afterNode = node.splitText(pos);
        const restNode = afterNode.splitText(matchLen);

        // Build fragment from HTML replacement
        const container = doc.createElement('div');
        container.innerHTML = matchReplacementHTML;
        const frag = doc.createDocumentFragment();
        while (container.firstChild) frag.appendChild(container.firstChild);

        afterNode.parentNode.replaceChild(frag, afterNode);

        changes += 1;

        // Continue scanning from the restNode (which contains the remainder of the original text)
        node = restNode;
        if (!node) break;

        text = node.nodeValue;
        lower = text.normalize('NFC').toLowerCase();
        pos = 0; // restart at beginning of the rest node
      }

      node = walker.nextNode();
    }

    // Return the modified body HTML and change count
    const outHtml = (doc.body && doc.body.innerHTML) ? doc.body.innerHTML : html;
    return { html: outHtml, changes };
  } catch (err) {
    console.error('Normalización segura falló, fallback no aplicado:', err);
    return { html, changes: 0 };
  }
}

// export for reuse by other modules
export { normalizeHtmlUsingTrie };

function inicializarInterfaz() {
  const btnNormalizar = document.getElementById("btn-normalizar");

  if (!btnNormalizar) {
    console.error("No se encontró el botón btn-normalizar.");
    return;
  }

  if (!btnNormalizar.dataset.listenerAttached) {
    btnNormalizar.addEventListener("click", normalizarTextoOutlook);
    btnNormalizar.dataset.listenerAttached = "true";
  }
}

Office.onReady((info) => {
  console.log(`Office está listo. Host: ${info.host}, Plataforma: ${info.platform}`);

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", inicializarInterfaz, { once: true });
  } else {
    inicializarInterfaz();
  }
});

// ==========================================
// FUNCIÓN PARA NORMALIZAR TEXTO EN OUTLOOK
// ==========================================
async function normalizarTextoOutlook() {
  try {
    console.log("Iniciando normalización en Outlook...");
    mostrarEstado("Procesando...", "info");
    
    // UI: deshabilitar botón y mostrar spinner mientras se procesa
    const btnNormalizar = document.getElementById("btn-normalizar");
    if (btnNormalizar && !btnNormalizar.dataset._busy) {
      btnNormalizar.dataset._origHtml = btnNormalizar.innerHTML;
      btnNormalizar.dataset._origDisabled = btnNormalizar.disabled ? '1' : '0';
      btnNormalizar.dataset._busy = '1';
      btnNormalizar.disabled = true;
      btnNormalizar.setAttribute('aria-disabled', 'true');
      btnNormalizar.innerHTML = `<svg class="spinner" width="16" height="16" viewBox="0 0 50 50" aria-hidden="true"><circle cx="25" cy="25" r="20" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-dasharray="31.4 31.4" transform="rotate(-90 25 25)"></circle></svg> Corrigiendo documento`;
    }

    function _restoreButton() {
      const b = document.getElementById("btn-normalizar");
      if (!b) return;
      if (b.dataset._origHtml !== undefined) {
        b.innerHTML = b.dataset._origHtml;
        delete b.dataset._origHtml;
      }
      if (b.dataset._origDisabled !== undefined) {
        b.disabled = b.dataset._origDisabled === '1';
        delete b.dataset._origDisabled;
      } else {
        b.disabled = false;
      }
      delete b.dataset._busy;
      b.removeAttribute('aria-disabled');
    }

    const item = Office.context.mailbox.item;
    
    // Obtener el cuerpo del correo como HTML
    item.body.getAsync(Office.CoercionType.Html, async (result) => {
      try {
        if (result.status === Office.AsyncResultStatus.Succeeded) {
          let bodyContent = result.value;
          console.log("📧 Contenido original obtenido");

          console.log('⏳ Iniciando normalización con trie...');
          const t0 = Date.now();

          let normalized;
          try {
            normalized = normalizeHtmlUsingTrie(bodyContent, dictionary);
          } catch (err) {
            console.error('❌ Normalizer threw an exception:', err);
            mostrarEstado('Error en el normalizador', 'error');
            try { _restoreButton(); } catch (e) {}
            return;
          }

          const t1 = Date.now();
          console.log(`✅ Normalizer finished in ${t1 - t0} ms. changes=${normalized && normalized.changes}`);

          const normalizedHtml = normalized && normalized.html ? normalized.html : bodyContent;
          const changes = normalized && typeof normalized.changes === 'number' ? normalized.changes : 0;

          if (changes > 0) {
            console.log(`🔁 Aplicando ${changes} cambio(s) al cuerpo...`);
            item.body.setAsync(normalizedHtml, { coercionType: Office.CoercionType.Html }, (asyncResult) => {
              if (asyncResult.status === Office.AsyncResultStatus.Failed) {
                console.error("❌ Error al actualizar el cuerpo del correo:", asyncResult.error && asyncResult.error.message);
                mostrarEstado("Error al actualizar el correo", "error");
              } else {
                console.log(`✅ Normalización completada. ${changes} cambio(s) realizado(s).`);
                mostrarEstado(`${changes} cambio(s) realizado(s)`, "success");
              }
              try { _restoreButton(); } catch (e) { /* ignore */ }
            });
          } else {
            console.log("ℹ️ No se encontraron coincidencias para reemplazar.");
            mostrarEstado("No se encontraron textos que coincidan con el diccionario", "info");
            try { _restoreButton(); } catch (e) { /* ignore */ }
          }
        } else {
          console.error("❌ Error al obtener el cuerpo del correo:", result.error && result.error.message);
          mostrarEstado("Error al obtener el contenido del correo", "error");
          try { _restoreButton(); } catch (e) {}
        }
      } catch (err) {
        console.error('❌ Error inesperado en callback de getAsync:', err);
        mostrarEstado('Error inesperado', 'error');
        try { _restoreButton(); } catch (e) {}
      }
    });
  } catch (error) {
    console.error("Error en Outlook:", error);
    mostrarEstado("Error: " + error.message, "error");
    try { _restoreButton(); } catch (e) {}
  }
}
